1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>Animation Gallery</title>
7	<link rel="preconnect" href="https://fonts.googleapis.com">
8	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;400;500;600&family=Space+Mono:wght@400;700&display=swap">
9	<style>
10	/* ─── Token System ─────────────────────────────────────────── */
11	:root {
12	  --bg:        #080b12;
13	  --surface:   #0d1220;
14	  --border:    rgba(255,255,255,0.07);
15	  --border-hi: rgba(100,180,255,0.35);
16	  --fg:        #e0e8f5;
17	  --fg-muted:  rgba(200,215,240,0.45);
18	  --accent:    #4fa3e8;
19	  --accent-glow: rgba(79,163,232,0.25);
20	  --active-bg: rgba(79,163,232,0.12);
21	  --panel-w:   280px;
22	  --font-ui:   'Space Grotesk', system-ui, sans-serif;
23	  --font-mono: 'Space Mono', 'Courier New', monospace;
24	  color-scheme: dark;
25	}
26	
27	/* ─── Reset ────────────────────────────────────────────────── */
28	*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
29	html, body { height: 100%; overflow: hidden; }
30	
31	body {
32	  background: var(--bg);
33	  color: var(--fg);
34	  font-family: var(--font-ui);
35	  display: flex;
36	  flex-direction: row;
37	}
38	
39	/* ─── Sidebar Panel ────────────────────────────────────────── */
40	#panel {
41	  width: var(--panel-w);
42	  min-width: var(--panel-w);
43	  height: 100%;
44	  background: var(--surface);
45	  border-right: 1px solid var(--border);
46	  display: flex;
47	  flex-direction: column;
48	  z-index: 10;
49	  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
50	}
51	
52	#panel-header {
53	  padding: 20px 20px 16px;
54	  border-bottom: 1px solid var(--border);
55	  flex-shrink: 0;
56	}
57	
58	#panel-header h1 {
59	  font-size: 11px;
60	  font-weight: 500;
61	  letter-spacing: 0.18em;
62	  text-transform: uppercase;
63	  color: var(--fg-muted);
64	  font-family: var(--font-mono);
65	}
66	
67	#panel-header .subtitle {
68	  margin-top: 4px;
69	  font-size: 18px;
70	  font-weight: 600;
71	  color: var(--fg);
72	  line-height: 1.2;
73	}
74	
75	/* ─── Animation List ───────────────────────────────────────── */
76	#anim-list {
77	  flex: 1;
78	  overflow-y: auto;
79	  padding: 10px 0;
80	  scrollbar-width: thin;
81	  scrollbar-color: rgba(255,255,255,0.1) transparent;
82	}
83	
84	#anim-list::-webkit-scrollbar { width: 4px; }
85	#anim-list::-webkit-scrollbar-track { background: transparent; }
86	#anim-list::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 2px; }
87	
88	.anim-item {
89	  display: flex;
90	  align-items: center;
91	  gap: 12px;
92	  padding: 12px 20px;
93	  cursor: pointer;
94	  transition: background 0.15s, border-color 0.15s;
95	  border-left: 2px solid transparent;
96	  user-select: none;
97	}
98	
99	.anim-item:hover {
100	  background: rgba(255,255,255,0.04);
101	  border-left-color: var(--border-hi);
102	}
103	
104	.anim-item.active {
105	  background: var(--active-bg);
106	  border-left-color: var(--accent);
107	}
108	
109	.anim-item.active .item-num { color: var(--accent); }
110	.anim-item.active .item-name { color: var(--fg); }
111	
112	.item-num {
113	  font-family: var(--font-mono);
114	  font-size: 10px;
115	  color: var(--fg-muted);
116	  min-width: 26px;
117	  transition: color 0.15s;
118	}
119	
120	.item-info { flex: 1; min-width: 0; }
121	
122	.item-name {
123	  font-size: 13px;
124	  font-weight: 500;
125	  color: rgba(200,215,240,0.75);
126	  white-space: nowrap;
127	  overflow: hidden;
128	  text-overflow: ellipsis;
129	  transition: color 0.15s;
130	}
131	
132	.item-file {
133	  margin-top: 2px;
134	  font-size: 10px;
135	  font-family: var(--font-mono);
136	  color: var(--fg-muted);
137	  white-space: nowrap;
138	  overflow: hidden;
139	  text-overflow: ellipsis;
140	  opacity: 0.6;
141	}
142	
143	.item-dot {
144	  width: 6px;
145	  height: 6px;
146	  border-radius: 50%;
147	  background: var(--border);
148	  flex-shrink: 0;
149	  transition: background 0.15s, box-shadow 0.15s;
150	}
151	
152	.anim-item.active .item-dot {
153	  background: var(--accent);
154	  box-shadow: 0 0 8px var(--accent-glow);
155	}
156	
157	/* ─── Footer Controls ──────────────────────────────────────── */
158	#panel-footer {
159	  padding: 16px 20px;
160	  border-top: 1px solid var(--border);
161	  flex-shrink: 0;
162	  display: flex;
163	  flex-direction: column;
164	  gap: 10px;
165	}
166	
167	.nav-row {
168	  display: flex;
169	  gap: 8px;
170	}
171	
172	.nav-btn {
173	  flex: 1;
174	  height: 36px;
175	  border: 1px solid var(--border);
176	  background: rgba(255,255,255,0.03);
177	  color: var(--fg-muted);
178	  font-family: var(--font-mono);
179	  font-size: 12px;
180	  border-radius: 6px;
181	  cursor: pointer;
182	  transition: all 0.15s;
183	  display: flex;
184	  align-items: center;
185	  justify-content: center;
186	  gap: 6px;
187	}
188	
189	.nav-btn:hover {
190	  background: rgba(255,255,255,0.07);
191	  color: var(--fg);
192	  border-color: var(--border-hi);
193	}
194	
195	.nav-btn svg { flex-shrink: 0; }
196	
197	#toggle-btn {
198	  height: 36px;
199	  border: 1px solid rgba(79,163,232,0.25);
200	  background: var(--active-bg);
201	  color: var(--accent);
202	  font-family: var(--font-mono);
203	  font-size: 11px;
204	  letter-spacing: 0.1em;
205	  border-radius: 6px;
206	  cursor: pointer;
207	  text-transform: uppercase;
208	  transition: all 0.15s;
209	}
210	
211	#toggle-btn:hover {
212	  background: rgba(79,163,232,0.2);
213	  border-color: var(--accent);
214	}
215	
216	/* ─── Main View ────────────────────────────────────────────── */
217	#main {
218	  flex: 1;
219	  position: relative;
220	  overflow: hidden;
221	  display: flex;
222	  flex-direction: column;
223	}
224	
225	/* Top bar */
226	#topbar {
227	  position: absolute;
228	  top: 0; left: 0; right: 0;
229	  height: 44px;
230	  display: flex;
231	  align-items: center;
232	  padding: 0 16px;
233	  gap: 12px;
234	  background: linear-gradient(to bottom, rgba(8,11,18,0.9), transparent);
235	  z-index: 5;
236	  pointer-events: none;
237	}
238	
239	#current-label {
240	  font-family: var(--font-mono);
241	  font-size: 11px;
242	  letter-spacing: 0.15em;
243	  color: var(--fg-muted);
244	  text-transform: uppercase;
245	}
246	
247	#panel-toggle-mobile {
248	  pointer-events: all;
249	  display: none;
250	  width: 36px;
251	  height: 36px;
252	  border: 1px solid var(--border);
253	  background: var(--surface);
254	  color: var(--fg);
255	  border-radius: 8px;
256	  cursor: pointer;
257	  align-items: center;
258	  justify-content: center;
259	}
260	
261	/* Frame */
262	#frame-wrap {
263	  flex: 1;
264	  position: relative;
265	}
266	
267	#anim-frame {
268	  position: absolute;
269	  inset: 0;
270	  width: 100%;
271	  height: 100%;
272	  border: none;
273	  display: block;
274	  background: #000;
275	}
276	
277	/* Empty state */
278	#empty-state {
279	  position: absolute;
280	  inset: 0;
281	  display: flex;
282	  flex-direction: column;
283	  align-items: center;
284	  justify-content: center;
285	  gap: 12px;
286	  color: var(--fg-muted);
287	  text-align: center;
288	  padding: 24px;
289	}
290	
291	#empty-state .es-icon {
292	  font-size: 40px;
293	  opacity: 0.4;
294	}
295	
296	#empty-state h2 {
297	  font-size: 16px;
298	  font-weight: 500;
299	  color: var(--fg);
300	  opacity: 0.6;
301	}
302	
303	#empty-state p {
304	  font-size: 13px;
305	  max-width: 280px;
306	  line-height: 1.6;
307	  opacity: 0.5;
308	}
309	
310	/* ─── Keyboard hint ────────────────────────────────────────── */
311	#kb-hint {
312	  position: absolute;
313	  bottom: 16px;
314	  right: 16px;
315	  font-family: var(--font-mono);
316	  font-size: 10px;
317	  letter-spacing: 0.1em;
318	  color: var(--fg-muted);
319	  opacity: 0.4;
320	  pointer-events: none;
321	  line-height: 1.8;
322	  text-align: right;
323	}
324	
325	kbd {
326	  display: inline-block;
327	  padding: 1px 5px;
328	  border: 1px solid rgba(255,255,255,0.15);
329	  border-radius: 3px;
330	  font-size: 9px;
331	  background: rgba(255,255,255,0.05);
332	}
333	
334	/* ─── Mobile ───────────────────────────────────────────────── */
335	@media (max-width: 640px) {
336	  :root { --panel-w: 240px; }
337	
338	  #panel {
339	    position: absolute;
340	    top: 0; left: 0; bottom: 0;
341	    transform: translateX(0);
342	    box-shadow: 4px 0 24px rgba(0,0,0,0.6);
343	  }
344	
345	  #panel.hidden {
346	    transform: translateX(-100%);
347	  }
348	
349	  #panel-toggle-mobile {
350	    display: flex;
351	  }
352	
353	  #kb-hint { display: none; }
354	}
355	</style>
356	</head>
357	<body>
358	
359	<!-- ─── Sidebar ─────────────────────────────────────── -->
360	<div id="panel">
361	  <div id="panel-header">
362	    <h1>Faust Studio</h1>
363	    <div class="subtitle">Animations</div>
364	  </div>
365	
366	  <div id="anim-list">
367	    <!-- populated by JS -->
368	  </div>
369	
370	  <div id="panel-footer">
371	    <div class="nav-row">
372	      <button class="nav-btn" id="prev-btn" title="Previous (←)">
373	        <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
374	          <path d="M7.5 2L3.5 6l4 4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
375	        </svg>
376	        Prev
377	      </button>
378	      <button class="nav-btn" id="next-btn" title="Next (→)">
379	        Next
380	        <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
381	          <path d="M4.5 2L8.5 6l-4 4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
382	        </svg>
383	      </button>
384	    </div>
385	    <button id="toggle-btn" title="Open in new tab">⬡ Open Fullscreen</button>
386	  </div>
387	</div>
388	
389	<!-- ─── Main View ───────────────────────────────────── -->
390	<div id="main">
391	  <div id="topbar">
392	    <button id="panel-toggle-mobile" aria-label="Toggle panel">
393	      <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
394	        <rect x="2" y="4" width="12" height="1.5" rx="0.75" fill="currentColor"/>
395	        <rect x="2" y="7.25" width="12" height="1.5" rx="0.75" fill="currentColor"/>
396	        <rect x="2" y="10.5" width="12" height="1.5" rx="0.75" fill="currentColor"/>
397	      </svg>
398	    </button>
399	    <span id="current-label">—</span>
400	  </div>
401	
402	  <div id="frame-wrap">
403	    <div id="empty-state">
404	      <div class="es-icon">◈</div>
405	      <h2>No animation selected</h2>
406	      <p>Pick one from the panel, or drop new <code>anim_*.html</code> files into this folder and reload.</p>
407	    </div>
408	    <iframe id="anim-frame" hidden title="Animation preview"></iframe>
409	  </div>
410	</div>
411	
412	<div id="kb-hint">
413	  <kbd>←</kbd><kbd>→</kbd> navigate &nbsp;·&nbsp; <kbd>F</kbd> fullscreen
414	</div>
415	
416	<script>
417	// ─── Animation registry ────────────────────────────────────────────────────
418	// Because this runs as a local file (file://) we cannot use fetch() to list
419	// siblings. Instead, we maintain a manifest here. The naming convention is
420	// anim_NNN_slug.html. Add new entries as files are created.
421	const ANIMS = [
422	  { id: "001", name: "Particle Field",   file: "anim_001_particle_field.html" },
423	  { id: "002", name: "Aurora Waves",     file: "anim_002_aurora_waves.html" },
424	  { id: "003", name: "Geometry Morph",   file: "anim_003_geometry_morph.html" },
425	];
426	
427	// ─── State ─────────────────────────────────────────────────────────────────
428	let current = -1;
429	
430	// ─── DOM refs ──────────────────────────────────────────────────────────────
431	const list       = document.getElementById('anim-list');
432	const frame      = document.getElementById('anim-frame');
433	const emptyState = document.getElementById('empty-state');
434	const label      = document.getElementById('current-label');
435	const prevBtn    = document.getElementById('prev-btn');
436	const nextBtn    = document.getElementById('next-btn');
437	const toggleBtn  = document.getElementById('toggle-btn');
438	const panel      = document.getElementById('panel');
439	const mobileBtn  = document.getElementById('panel-toggle-mobile');
440	
441	// ─── Build list ────────────────────────────────────────────────────────────
442	function buildList() {
443	  list.innerHTML = '';
444	  ANIMS.forEach((anim, idx) => {
445	    const el = document.createElement('div');
446	    el.className = 'anim-item';
447	    el.dataset.idx = idx;
448	    el.innerHTML = `
449	      <span class="item-num">${anim.id}</span>
450	      <div class="item-info">
451	        <div class="item-name">${anim.name}</div>
452	        <div class="item-file">${anim.file}</div>
453	      </div>
454	      <div class="item-dot"></div>
455	    `;
456	    el.addEventListener('click', () => select(idx));
457	    list.appendChild(el);
458	  });
459	}
460	
461	// ─── Select ────────────────────────────────────────────────────────────────
462	function select(idx) {
463	  if (idx < 0 || idx >= ANIMS.length) return;
464	  current = idx;
465	  const anim = ANIMS[idx];
466	
467	  // Update list highlight
468	  document.querySelectorAll('.anim-item').forEach((el, i) => {
469	    el.classList.toggle('active', i === idx);
470	  });
471	
472	  // Scroll into view
473	  const activeEl = list.querySelector('.anim-item.active');
474	  if (activeEl) activeEl.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
475	
476	  // Load iframe
477	  frame.hidden = false;
478	  emptyState.hidden = true;
479	  frame.src = anim.file;
480	  label.textContent = `${anim.id} · ${anim.name}`;
481	
482	  // Persist last selection
483	  try { localStorage.setItem('fg-anim-idx', idx); } catch (_) {}
484	}
485	
486	// ─── Navigation ────────────────────────────────────────────────────────────
487	function prev() { select(current <= 0 ? ANIMS.length - 1 : current - 1); }
488	function next() { select(current >= ANIMS.length - 1 ? 0 : current + 1); }
489	
490	prevBtn.addEventListener('click', prev);
491	nextBtn.addEventListener('click', next);
492	
493	// ─── Fullscreen / open ─────────────────────────────────────────────────────
494	toggleBtn.addEventListener('click', () => {
495	  if (current < 0) return;
496	  window.open(ANIMS[current].file, '_blank');
497	});
498	
499	// ─── Mobile panel toggle ───────────────────────────────────────────────────
500	mobileBtn.addEventListener('click', () => {
501	  panel.classList.toggle('hidden');
502	});
503	
504	// ─── Keyboard ─────────────────────────────────────────────────────────────
505	document.addEventListener('keydown', e => {
506	  if (e.target.tagName === 'INPUT') return;
507	  if (e.key === 'ArrowLeft'  || e.key === 'a' || e.key === 'A') { e.preventDefault(); prev(); }
508	  if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') { e.preventDefault(); next(); }
509	  if (e.key === 'f' || e.key === 'F') {
510	    if (current >= 0) window.open(ANIMS[current].file, '_blank');
511	  }
512	  // Number keys 1–9
513	  const n = parseInt(e.key);
514	  if (!isNaN(n) && n >= 1 && n <= ANIMS.length) select(n - 1);
515	});
516	
517	// ─── Init ──────────────────────────────────────────────────────────────────
518	buildList();
519	
520	// Restore last or load first
521	let startIdx = 0;
522	try {
523	  const saved = parseInt(localStorage.getItem('fg-anim-idx'));
524	  if (!isNaN(saved) && saved >= 0 && saved < ANIMS.length) startIdx = saved;
525	} catch (_) {}
526	
527	select(startIdx);
528	</script>
529	</body>
530	</html>
