1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>Animation Vault</title>
7	<link rel="preconnect" href="https://fonts.googleapis.com">
8	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500&display=swap">
9	<style>
10	/* ── Tokens ─────────────────────────────────────────────────
11	   Two near-identical darks. Everything recedes; content is
12	   the room. Obsidian-register palette.
13	────────────────────────────────────────────────────────── */
14	:root {
15	  --bg:       #1e1e1e;
16	  --sidebar:  #161616;
17	  --hover:    rgba(255,255,255,0.052);
18	  --active:   rgba(255,255,255,0.088);
19	  --fg:       rgba(218,218,218,0.82);
20	  --fg-dim:   rgba(180,180,180,0.36);
21	  --accent:   #7c6fcd;
22	  --panel-w:  228px;
23	  --radius:   4px;
24	  --font:     'Inter', system-ui, sans-serif;
25	  color-scheme: dark;
26	}
27	
28	*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
29	html, body { height: 100%; overflow: hidden; }
30	body { background: var(--bg); color: var(--fg); font-family: var(--font); font-size: 13px; display: flex; }
31	
