107	
108	@keyframes r1 {
109	  from { transform: translate(-50%,-50%) rotateX(69deg) rotateZ(0deg); }
110	  to   { transform: translate(-50%,-50%) rotateX(69deg) rotateZ(360deg); }
111	}
112	@keyframes r2 {
113	  from { transform: translate(-50%,-50%) rotateX(63deg) rotateZ(360deg); }
114	  to   { transform: translate(-50%,-50%) rotateX(63deg) rotateZ(0deg); }
115	}
116	@keyframes r3 {
117	  from { transform: translate(-50%,-50%) rotateX(57deg) rotateZ(0deg); }
118	  to   { transform: translate(-50%,-50%) rotateX(57deg) rotateZ(360deg); }
119	}
120	@keyframes r4 {
121	  from { transform: translate(-50%,-50%) rotateX(51deg) rotateZ(360deg); }
122	  to   { transform: translate(-50%,-50%) rotateX(51deg) rotateZ(0deg); }
123	}
124	
125	/* ambient glow rings */
126	.glow-ring {
127	  position: absolute;
128	  left: 50%; top: 50%;
129	  border-radius: 50%;
130	  border: 1px solid rgba(255,216,107,.12);
131	  transform: translate(-50%,-50%);
132	  pointer-events: none;
133	}
134	.glow-ring-1 { width: 400px; height: 400px; border-color: rgba(255,216,107,.08); }
135	.glow-ring-2 { width: 375px; height: 375px; border-color: rgba(255,216,107,.13); }
136	
137	/* ── PARTICLES ── */
138	.particle-field {
139	  position: absolute;
140	  inset: 0;
141	  z-index: 28;
142	  pointer-events: none;
143	}
144	
145	.particle {
146	  position: absolute;
147	  left: 50%; top: 50%;
148	  width: var(--sz); height: var(--sz);
149	  border-radius: 50%;
150	  opacity: 0;
151	  background: radial-gradient(
152	    circle at 30% 30%,
153	    #fff 0 14%,
154	    #ffe88a 32%,
155	    #c87a00 60%,
156	    transparent 76%
157	  );
158	  box-shadow:
159	    0 0 5px rgba(255,255,255,.9),
160	    0 0 14px rgba(255,200,60,.8);
161	  transform: translate(-50%,-50%) rotate(var(--ang)) translateX(var(--rad)) rotate(calc(var(--ang) * -1));
162	}
163	.particle.orbit {
164	  animation: pOrbit var(--ot) cubic-bezier(.37,0,.63,1) forwards;
165	}
166	.particle.compress {
167	  animation: pCompress var(--ct) cubic-bezier(.15,.65,.06,1) forwards;
168	}
169	
170	@keyframes pOrbit {
171	  0%   { opacity:0; transform:translate(-50%,-50%) rotate(var(--ang)) translateX(var(--rad)) rotate(calc(var(--ang)*-1)) scale(.2); }
172	  12%  { opacity:var(--op); }
173	  52%  { opacity:var(--op); transform:translate(-50%,-50%) rotate(calc(var(--ang)+150deg)) translateX(calc(var(--rad)*.96)) rotate(calc((var(--ang)+150deg)*-1)) scale(1); }
174	  100% { opacity:var(--op); transform:translate(-50%,-50%) rotate(calc(var(--ang)+340deg)) translateX(calc(var(--rad)*.78)) rotate(calc((var(--ang)+340deg)*-1)) scale(.8); }
175	}
176	@keyframes pCompress {
177	  0%   { opacity:1; transform:translate(-50%,-50%) rotate(var(--ang2)) translateX(var(--rad2)) rotate(calc(var(--ang2)*-1)) scale(1); }
178	  30%  { transform:translate(-50%,-50%) rotate(calc(var(--ang2)+170deg)) translateX(calc(var(--rad2)*.45)) rotate(calc((var(--ang2)+170deg)*-1)) scale(1.08); }
179	  66%  { transform:translate(-50%,-50%) rotate(calc(var(--ang2)+350deg)) translateX(48px) rotate(calc((var(--ang2)+350deg)*-1)) scale(.82); }
180	  88%  { opacity:.96; transform:translate(-50%,-50%) rotate(calc(var(--ang2)+430deg)) translateX(17px) rotate(calc((var(--ang2)+430deg)*-1)) scale(.55); }
181	  100% { opacity:0; transform:translate(-50%,-50%) scale(0); filter:blur(8px); }
182	}
183	
184	/* ── DEPOSIT BURST EFFECTS ── */
185	.distortion {
186	  position: absolute;
187	  width: 900px; height: 900px;
188	  border-radius: 50%;
189	  z-index: 4; pointer-events: none; opacity: 0;
190	  background: radial-gradient(circle, transparent 0 17%, rgba(200,140,0,.07) 25%, transparent 43%);
191	  filter: blur(10px);
192	}
193	.distortion.active { animation: distort 4.6s ease-in-out forwards; }
194	@keyframes distort {
195	  0%  { opacity:0; transform:scale(.8); }
196	  12% { opacity:.85; transform:scale(1.03); }
197	  28% { opacity:.55; transform:scale(1.10); }
198	  46% { opacity:.15; transform:scale(.72); }
199	  62% { opacity:0;   transform:scale(.40); }
200	  76% { opacity:.75; transform:scale(.78); }
201	  100%{ opacity:0;   transform:scale(1.12); }
202	}
203	
204	.shockwave {
205	  position: absolute; left: 50%; top: 50%;
206	  width: 60px; height: 60px; z-index: 86;
207	  border: 2px solid rgba(255,216,107,.95);
208	  border-radius: 50%; opacity: 0;
209	  transform: translate(-50%,-50%) scale(0);
210	  pointer-events: none;
211	}
212	.shockwave.active { animation: shock 700ms ease-out forwards; }
213	@keyframes shock {
214	  from { opacity:.95; transform:translate(-50%,-50%) scale(.2); }
215	  to   { opacity:0;   transform:translate(-50%,-50%) scale(18); }
216	}
217	
218	.supernova {
219	  position: absolute; left: 50%; top: 50%;
220	  width: 26px; height: 8px; z-index: 90;
221	  opacity: 0; pointer-events: none;
222	  transform: translate(-50%,-50%) scaleX(0);
223	}
224	.supernova::before {
225	  content: "";
226	  position: absolute; left: 50%; top: 50%;
227	  width: 100%; height: 5px;
228	  transform: translate(-50%,-50%);
229	  border-radius: 999px; background: white;
230	  box-shadow:
231	    0 0 7px #fff, 0 0 24px #fff,
232	    0 0 60px rgba(255,220,80,.96),
233	    0 0 120px rgba(200,140,0,.92);
234	}
235	.supernova::after {
236	  content: "";
237	  position: absolute; left: 50%; top: 50%;
238	  width: 100%; height: 46px;
239	  transform: translate(-50%,-50%);
240	  background: linear-gradient(90deg, transparent, rgba(255,200,60,.58), rgba(255,255,200,.96), rgba(255,200,60,.58), transparent);
241	  filter: blur(10px);
242	}
243	.supernova.active { animation: nova 480ms cubic-bezier(.06,.88,.12,1) forwards; }
244	@keyframes nova {
245	  0%  { opacity:0;    transform:translate(-50%,-50%) scaleX(0); }
246	  10% { opacity:1;    transform:translate(-50%,-50%) scaleX(.12); }
247	  34% { opacity:1;    transform:translate(-50%,-50%) scaleX(5); }
248	  62% { opacity:.95;  transform:translate(-50%,-50%) scaleX(22); }
249	  100%{ opacity:0;    transform:translate(-50%,-50%) scaleX(52); }
250	}
251	
252	.rebirth {
253	  position: absolute; left: 50%; top: 50%;
254	  width: 40px; height: 40px; z-index: 52;
255	  border: 2px solid rgba(255,216,107,.9);
256	  border-radius: 50%; opacity: 0;
257	  transform: translate(-50%,-50%) scale(0);
258	  pointer-events: none;
259	}
260	.rebirth.active { animation: rebirth 1s cubic-bezier(.08,.82,.12,1) forwards; }
261	@keyframes rebirth {
262	  0%  { opacity:0;   transform:translate(-50%,-50%) scale(.05); filter:blur(5px); }
263	  24% { opacity:1;   transform:translate(-50%,-50%) scale(.55); filter:blur(0); }
264	  62% { opacity:.85; transform:translate(-50%,-50%) scale(2.2); }
265	  100%{ opacity:0;   transform:translate(-50%,-50%) scale(4.8); filter:blur(4px); }
266	}
267	
268	.matter-field {
269	  position: absolute; inset: 0; z-index: 55; pointer-events: none;
270	}
271	.matter {
272	  position: absolute; left: 50%; top: 50%;
273	  width: var(--sz); height: var(--sz);
274	  border-radius: 50%; opacity: 0;
275	  background: radial-gradient(circle at 30% 30%, #fff 0 12%, #ffe07a 32%, #c87a00 62%, transparent 78%);
276	  box-shadow: 0 0 5px #fff, 0 0 14px rgba(255,200,60,.92);
277	  transform: translate(-50%,-50%) rotate(var(--ang)) translateX(3px);
278	}
279	.matter.active { animation: matterOut var(--dur) cubic-bezier(.08,.84,.13,1) forwards; }
280	@keyframes matterOut {
281	  0%  { opacity:0; transform:translate(-50%,-50%) rotate(var(--ang)) translateX(3px) scale(.1); }
282	  10% { opacity:1; }
283	  75% { opacity:1; }
284	  100%{ opacity:0; transform:translate(-50%,-50%) rotate(var(--ang)) translateX(var(--dist)) scale(.42); }
285	}
286	
287	/* ── BALANCE READOUT ── */
288	.readout {
289	  position: absolute; inset: 0;
290	  display: flex; flex-direction: column;
291	  align-items: center; justify-content: center;
292	  pointer-events: none; z-index: 60;
293	}
294	.readout-label {
295	  font-family: monospace;
296	  font-size: 10px;
297	  color: rgba(255,216,107,.45);
298	  letter-spacing: .25em;
299	  text-transform: uppercase;
300	  margin-bottom: 4px;
301	}
302	.readout-value {
303	  font-family: monospace;
304	  font-weight: 900;
305	  font-size: 1.75rem;
306	  color: #ffd86b;
307	  line-height: 1;
308	  text-shadow: 0 0 22px rgba(255,216,107,.5);
309	  transition: text-shadow 1.4s ease;
310	}
311	.readout-sub {
312	  font-family: monospace;
313	  font-size: 10px;
314	  color: rgba(255,216,107,.3);
315	  margin-top: 6px;
316	}
317	
318	/* ── INPUT + BUTTON ── */
319	.controls {
320	  display: flex;
321	  flex-direction: column;
322	  align-items: center;
323	  gap: 16px;
324	  width: 100%;
325	  margin-top: 8px;
326	  position: relative;
327	  z-index: 100;
328	}
329	
330	.input-wrap {
331	  position: relative;
332	  display: flex;
333	  align-items: center;
334	  justify-content: center;
335	}
336	.hours-input {
337	  width: 260px;
338	  background: transparent;
339	  border: none;
340	  border-bottom: 2px solid rgba(255,216,107,.25);
341	  outline: none;
342	  color: #f5f0e8;
343	  font-family: monospace;
344	  font-weight: 900;
345	  font-size: 3rem;
346	  text-align: center;
347	  padding: 4px 28px 8px 4px;
348	  caret-color: #ffd86b;
349	  transition: border-color .2s;
350	}
351	.hours-input:focus { border-bottom-color: #ffd86b; }
352	.hours-input::placeholder { color: rgba(255,216,107,.1); }
353	.hours-input:disabled { opacity: .35; }
354	.input-unit {
355	  position: absolute;
356	  right: 4px; bottom: 12px;
357	  color: rgba(255,216,107,.35);
358	  font-family: monospace;
359	  font-size: .85rem;
360	  pointer-events: none;
361	}
362	
363	.deposit-btn {
364	  width: 260px;
365	  padding: 16px 0;
366	  border-radius: 16px;
367	  background: #ffd86b;
368	  color: #0c0914;
369	  font-family: monospace;
370	  font-weight: 900;
371	  font-size: 13px;
372	  letter-spacing: .2em;
373	  text-transform: uppercase;
374	  border: none;
375	  cursor: pointer;
376	  transition: background .15s, transform .1s, box-shadow .15s;
377	  box-shadow: 0 0 32px rgba(255,216,107,.28);
378	  display: flex;
379	  align-items: center;
380	  justify-content: center;
381	  gap: 8px;
382	}
383	.deposit-btn:hover:not(:disabled) {
384	  background: #ffe485;
385	  box-shadow: 0 0 44px rgba(255,216,107,.45);
386	}
387	.deposit-btn:active:not(:disabled) { transform: scale(.97); }
388	.deposit-btn:disabled {
389	  background: rgba(255,216,107,.12);
390	  color: rgba(255,216,107,.25);
391	  cursor: not-allowed;
392	  box-shadow: none;
393	}
394	
395	.spinner {
396	  width: 14px; height: 14px;
397	  border-radius: 50%;
398	  border: 2px solid rgba(12,9,20,.25);
399	  border-top-color: #0c0914;
400	  animation: spin .7s linear infinite;
401	  display: none;
402	}
403	@keyframes spin { to { transform: rotate(360deg); } }
404	
405	.error-msg {
406	  color: #f87171;
407	  font-family: monospace;
408	  font-size: 12px;
409	  text-align: center;
410	  max-width: 260px;
411	  min-height: 18px;
412	}
413	
414	.alltime {
415	  color: rgba(255,216,107,.18);
416	  font-family: monospace;
417	  font-size: 10px;
418	  letter-spacing: .2em;
419	  text-transform: uppercase;
420	  text-align: center;
421	  margin-top: 4px;
422	}
423	</style>
424	</head>
425	<body>
426	
427	<div class="scene">
428	  <div class="stars"></div>
429	
430	  <!-- ── ORB ── -->
431	  <div class="orb-wrap">
432	    <div class="glow-ring glow-ring-1"></div>
433	    <div class="glow-ring glow-ring-2"></div>
434	
435	    <div class="distortion" id="distortion"></div>
436	
437	    <div class="ring ring-1"></div>
438	    <div class="ring ring-2"></div>
439	    <div class="ring ring-3"></div>
440	    <div class="ring ring-4"></div>
441	
442	    <div class="core"></div>
443	
444	    <div class="particle-field" id="particleField"></div>
445	
446	    <div class="shockwave"    id="shockwave"></div>
447	    <div class="supernova"    id="supernova"></div>
448	    <div class="rebirth"      id="rebirth"></div>
449	    <div class="matter-field" id="matterField"></div>
450	
451	    <div class="readout">
452	      <div class="readout-label">Balance</div>
453	      <div class="readout-value" id="balanceDisplay">7h 23m 14s</div>
454	      <div class="readout-sub"   id="balanceSub">7.39h total</div>
455	    </div>
456	  </div>
457	
458	  <!-- ── CONTROLS ── -->
459	  <div class="controls">
460	    <div class="input-wrap">
461	      <input
462	        class="hours-input"
463	        type="number"
464	        id="hoursInput"
465	        min="0"
466	        step="0.25"
467	        placeholder="0"
468	      />
469	      <span class="input-unit">h</span>
470	    </div>
471	
472	    <button class="deposit-btn" id="depositBtn" onclick="triggerDeposit()">
473	      <span class="spinner" id="spinner"></span>
474	      <span id="btnLabel">+ Deposit Hours</span>
475	    </button>
476	
477	    <div class="error-msg" id="errorMsg"></div>
478	    <div class="alltime"   id="alltimeLabel">All-time — 7h 23m 14s</div>
479	  </div>
480	</div>
481	
482	<script>
483	// ── Mock state (replace with real API calls when re-integrating) ──────────────
484	let balanceSec  = 7 * 3600 + 23 * 60 + 14;   // 7h 23m 14s mock balance
485	let totalEarned = balanceSec;
486	let depositing  = false;
487	
488	// ── Format helpers ────────────────────────────────────────────────────────────
489	function fmt(sec) {
490	  const s = Math.floor(sec);
491	  const d = Math.floor(s / 86400);
492	  const h = Math.floor((s % 86400) / 3600);
493	  const m = Math.floor((s % 3600) / 60);
494	  const ss = s % 60;
495	  if (d > 0) return `${d}d ${h}h ${m}m`;
496	  if (h > 0) return `${h}h ${m}m ${ss}s`;
497	  if (m > 0) return `${m}m ${ss}s`;
498	  return `${ss}s`;
499	}
500	
501	// ── Animated roll-up ──────────────────────────────────────────────────────────
502	let animRaf = null;
503	function rollTo(from, to, duration = 1100) {
504	  if (animRaf) cancelAnimationFrame(animRaf);
505	  const t0 = performance.now();
506	  function tick(now) {
507	    const p    = Math.min((now - t0) / duration, 1);
508	    const ease = p === 1 ? 1 : 1 - Math.pow(2, -10 * p);
509	    const val  = from + (to - from) * ease;
510	    document.getElementById('balanceDisplay').textContent = fmt(val);
511	    document.getElementById('balanceSub').textContent = (val / 3600).toFixed(2) + 'h total';
512	    if (p < 1) animRaf = requestAnimationFrame(tick);
513	  }
514	  animRaf = requestAnimationFrame(tick);
515	}
516	
517	function updateAltime() {
518	  document.getElementById('alltimeLabel').textContent = 'All-time — ' + fmt(totalEarned);
519	}
520	
521	// ── Animation helpers ─────────────────────────────────────────────────────────
522	function restart(el, cls) {
523	  el.classList.remove(cls);
524	  void el.offsetWidth;
525	  el.classList.add(cls);
526	}
527	
528	function spawnParticles(count = 160) {
529	  const field = document.getElementById('particleField');
530	  field.innerHTML = '';
531	  for (let i = 0; i < count; i++) {
532	    const p      = document.createElement('div');
533	    const radius = 140 + Math.random() * 360;
534	    const angle  = Math.random() * 360;
535	    const size   = 1.5 + Math.random() * 5;
536	    const op     = .35 + Math.random() * .65;
537	    const ot     = 900 + Math.random() * 1400;
538	    const ct     = 700 + Math.random() * 600;
539	    p.className = 'particle';
540	    p.style.setProperty('--rad', `${radius}px`);
541	    p.style.setProperty('--ang', `${angle}deg`);
542	    p.style.setProperty('--sz',  `${size}px`);
543	    p.style.setProperty('--op',  op);
544	    p.style.setProperty('--ot',  `${ot}ms`);
545	    p.style.setProperty('--ct',  `${ct}ms`);
546	    field.appendChild(p);
547	  }
548	  requestAnimationFrame(() => {
549	    [...field.children].forEach((c, i) => {
550	      setTimeout(() => c.classList.add('orbit'), Math.random() * 600 + i * 2);
551	    });
552	  });
553	}
554	
555	function compressParticles() {
556	  const field = document.getElementById('particleField');
557	  [...field.children].forEach((c, i) => {
558	    const rad = c.style.getPropertyValue('--rad');
559	    const ang = parseFloat(c.style.getPropertyValue('--ang'));
560	    c.style.setProperty('--rad2', rad);
561	    c.style.setProperty('--ang2', `${ang + Math.random() * 90}deg`);
562	    setTimeout(() => {
563	      c.classList.remove('orbit');
564	      c.classList.add('compress');
565	    }, Math.random() * 400 + i * .7);
566	  });
567	}
568	
569	function spawnMatter(count = 130) {
570	  const field = document.getElementById('matterField');
571	  field.innerHTML = '';
572	  for (let i = 0; i < count; i++) {
573	    const p        = document.createElement('div');
574	    const angle    = Math.random() * 360;
575	    const distance = 200 + Math.random() * 440;
576	    const dur      = 800 + Math.random() * 900;
577	    const size     = 1.5 + Math.random() * 5.5;
578	    p.className = 'matter';
579	    p.style.setProperty('--ang',  `${angle}deg`);
580	    p.style.setProperty('--dist', `${distance}px`);
581	    p.style.setProperty('--dur',  `${dur}ms`);
582	    p.style.setProperty('--sz',   `${size}px`);
583	    field.appendChild(p);
584	    setTimeout(() => p.classList.add('active'), 400 + Math.random() * 500);
585	  }
586	}
587	
588	const wait = ms => new Promise(r => setTimeout(r, ms));
589	
590	// ── Deposit sequence ──────────────────────────────────────────────────────────
591	async function triggerDeposit() {
592	  if (depositing) return;
593	  const input = document.getElementById('hoursInput');
594	  const h = parseFloat(input.value);
595	  if (!h || h <= 0) {
596	    showError('Enter a valid number of hours');
597	    return;
598	  }
599	
600	  depositing = true;
601	  setLoading(true);
602	  clearError();
603	
604	  // Phase 1: distortion + particle spawn
605	  restart(document.getElementById('distortion'), 'active');
606	  await wait(90);
607	  spawnParticles(180);
608	  await wait(1050);
609	
610	  // Phase 2: compress
611	  compressParticles();
612	  await wait(280);
613	
614	  // Phase 3: shockwave + supernova
615	  restart(document.getElementById('shockwave'), 'active');
616	  restart(document.getElementById('supernova'), 'active');
617	  await wait(480);
618	
619	  // Phase 4: gold matter + rebirth
620	  spawnMatter(140);
621	  restart(document.getElementById('rebirth'), 'active');
622	
623	  // Phase 5: commit balance
624	  const added = h * 3600;
625	  const prev  = balanceSec;
626	  balanceSec  += added;
627	  totalEarned += added;
628	  rollTo(prev, balanceSec);
629	  updateAltime();
630	  input.value = '';
631	
632	  await wait(1200);
633	  depositing = false;
634	  setLoading(false);
635	}
636	
637	function setLoading(on) {
638	  const btn     = document.getElementById('depositBtn');
639	  const spinner = document.getElementById('spinner');
640	  const label   = document.getElementById('btnLabel');
641	  const input   = document.getElementById('hoursInput');
642	  btn.disabled    = on;
643	  input.disabled  = on;
644	  spinner.style.display = on ? 'block' : 'none';
645	  label.textContent = on ? 'Depositing' : '+ Deposit Hours';
646	}
647	
648	function showError(msg) {
649	  document.getElementById('errorMsg').textContent = msg;
650	}
651	function clearError() {
652	  document.getElementById('errorMsg').textContent = '';
653	}
654	
655	// Enter key submits
656	document.getElementById('hoursInput').addEventListener('keydown', e => {
657	  if (e.key === 'Enter') triggerDeposit();
658	  clearError();
659	});
660	document.getElementById('hoursInput').addEventListener('input', clearError);
661	
662	// ── Idle ambient particle loop ────────────────────────────────────────────────
663	(async function idleLoop() {
664	  while (true) {
665	    spawnParticles(120);
666	    await wait(1200);
667	    compressParticles();
668	    await wait(3200);
669	  }
670	})();
671	
672	// Init display
673	updateAltime();
674	</script>
675	</body>
676	</html>
