266	async function scanDir(urlPath) {
267	  const res = await fetch(urlPath);
268	  if (!res.ok) throw new Error(`HTTP ${res.status} for ${urlPath}`);
269	  const html  = await res.text();
270	  const doc   = new DOMParser().parseFromString(html, 'text/html');
271	  const links = [...doc.querySelectorAll('a[href]')];
272	
273	  const nodes = [];
274	  for (const a of links) {
275	    const href = a.getAttribute('href');
276	    // Skip parent dir links and query strings
277	    if (!href || href.startsWith('?') || href === '../' || href === '/') continue;
278	
279	    const isDir  = href.endsWith('/');
280	    const isHtml = href.toLowerCase().endsWith('.html');
281	
282	    if (!isDir && !isHtml) continue;
283	
284	    // Build the full URL path for fetching, and the relative path for iframes
285	    const fullUrl  = new URL(href, location.origin + urlPath).pathname;
286	    // Relative path from root for iframe src (strip leading /)
287	    const relPath  = fullUrl.replace(/^\//, '');
